    CreateClusterRequest.add_member(:version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'version', traits: {"smithy.api#documentation" => "<p>The desired Kubernetes version for your cluster. If you don't specify a value here, the\n            default version available in Amazon EKS is used.</p>\n         <note>\n            <p>The default version might not be the latest version available.</p>\n         </note>"}))
    CreateClusterRequest.add_member(:role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'roleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the IAM role that provides permissions for the Kubernetes control plane\n            to make calls to Amazon Web Services API operations on your behalf. For more information, see <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/service_IAM_role.html\">Amazon EKS Service\n                IAM Role</a> in the <i>\n               <i>Amazon EKS User Guide</i>\n            </i>.</p>", "smithy.api#required" => {}}))
    CreateClusterRequest.add_member(:resources_vpc_config, Smithy::Schema::Shapes::ShapeRef.new(shape: VpcConfigRequest, location_name: 'resourcesVpcConfig', traits: {"smithy.api#documentation" => "<p>The VPC configuration that's used by the cluster control plane. Amazon EKS VPC resources\n            have specific requirements to work properly with Kubernetes. For more information, see <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/network_reqs.html\">Cluster VPC\n                Considerations</a> and <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/sec-group-reqs.html\">Cluster Security Group Considerations</a> in the\n            <i>Amazon EKS User Guide</i>. You must specify at least two subnets. You can specify up to five\n            security groups. However, we recommend that you use a dedicated security group for your\n            cluster control plane.</p>", "smithy.api#required" => {}}))
    CreateClusterRequest.add_member(:kubernetes_network_config, Smithy::Schema::Shapes::ShapeRef.new(shape: KubernetesNetworkConfigRequest, location_name: 'kubernetesNetworkConfig', traits: {"smithy.api#documentation" => "<p>The Kubernetes network configuration for the cluster.</p>"}))
    CreateClusterRequest.add_member(:logging, Smithy::Schema::Shapes::ShapeRef.new(shape: Logging, location_name: 'logging', traits: {"smithy.api#documentation" => "<p>Enable or disable exporting the Kubernetes control plane logs for your cluster to CloudWatch Logs .\n            By default, cluster control plane logs aren't exported to CloudWatch Logs . For more information,\n            see <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/control-plane-logs.html\">Amazon EKS\n                Cluster control plane logs</a> in the\n            <i>\n               <i>Amazon EKS User Guide</i>\n            </i>.</p>\n         <note>\n            <p>CloudWatch Logs ingestion, archive storage, and data scanning rates apply to exported\n                control plane logs. For more information, see <a href=\"http://aws.amazon.com/cloudwatch/pricing/\">CloudWatch Pricing</a>.</p>\n         </note>"}))
    CreateClusterRequest.add_member(:client_request_token, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'clientRequestToken', traits: {"smithy.api#documentation" => "<p>A unique, case-sensitive identifier that you provide to ensure\nthe idempotency of the request.</p>", "smithy.api#idempotencyToken" => {}}))
    CreateClusterRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagMap, location_name: 'tags', traits: {"smithy.api#documentation" => "<p>Metadata that assists with categorization and organization.\n            Each tag consists of a key and an optional value. You define both. Tags don't\n            propagate to any other cluster or Amazon Web Services resources.</p>"}))
    CreateClusterRequest.add_member(:encryption_config, Smithy::Schema::Shapes::ShapeRef.new(shape: EncryptionConfigList, location_name: 'encryptionConfig', traits: {"smithy.api#documentation" => "<p>The encryption configuration for the cluster.</p>"}))
    CreateClusterRequest.add_member(:outpost_config, Smithy::Schema::Shapes::ShapeRef.new(shape: OutpostConfigRequest, location_name: 'outpostConfig', traits: {"smithy.api#documentation" => "<p>An object representing the configuration of your local Amazon EKS cluster on an Amazon Web Services\n            Outpost. Before creating a local cluster on an Outpost, review <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/eks-outposts-local-cluster-overview.html\">Local clusters\n                for Amazon EKS on Amazon Web Services Outposts</a> in the <i>Amazon EKS User Guide</i>. This object isn't\n            available for creating Amazon EKS clusters on the Amazon Web Services cloud.</p>"}))
    CreateClusterRequest.add_member(:access_config, Smithy::Schema::Shapes::ShapeRef.new(shape: CreateAccessConfigRequest, location_name: 'accessConfig', traits: {"smithy.api#documentation" => "<p>The access configuration for the cluster.</p>"}))
    CreateClusterRequest.add_member(:bootstrap_self_managed_addons, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedBoolean, location_name: 'bootstrapSelfManagedAddons', traits: {"smithy.api#documentation" => "<p>If you set this value to <code>False</code> when creating a cluster, the default\n            networking add-ons will not be installed.</p>\n         <p>The default networking add-ons include <code>vpc-cni</code>, <code>coredns</code>, and\n                <code>kube-proxy</code>.</p>\n         <p>Use this option when you plan to install third-party alternative add-ons or\n            self-manage the default networking add-ons.</p>"}))
    CreateClusterRequest.add_member(:upgrade_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: UpgradePolicyRequest, location_name: 'upgradePolicy', traits: {"smithy.api#documentation" => "<p>New clusters, by default, have extended support enabled. You can disable extended\n            support when creating a cluster by setting this value to <code>STANDARD</code>.</p>"}))
    CreateClusterRequest.add_member(:zonal_shift_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ZonalShiftConfigRequest, location_name: 'zonalShiftConfig', traits: {"smithy.api#documentation" => "<p>Enable or disable ARC zonal shift for the cluster. If zonal shift is enabled, Amazon Web Services\n            configures zonal autoshift for the cluster.</p>\n         <p>Zonal shift is a feature of Amazon Application Recovery Controller (ARC). ARC zonal shift is designed to be a\n            temporary measure that allows you to move traffic for a resource away from an impaired\n            AZ until the zonal shift expires or you cancel it. You can extend the zonal shift if\n            necessary.</p>\n         <p>You can start a zonal shift for an Amazon EKS cluster, or you can allow Amazon Web Services to do it for\n            you by enabling <i>zonal autoshift</i>. This shift updates the flow of\n            east-to-west network traffic in your cluster to only consider network endpoints for Pods\n            running on worker nodes in healthy AZs. Additionally, any ALB or NLB handling ingress\n            traffic for applications in your Amazon EKS cluster will automatically route traffic to\n            targets in the healthy AZs. For more information about zonal shift in EKS, see <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/zone-shift.html\">Learn about\n                Amazon Application Recovery Controller (ARC) Zonal Shift in Amazon EKS</a> in the\n                <i>\n               <i>Amazon EKS User Guide</i>\n            </i>.</p>"}))
    CreateClusterRequest.add_member(:remote_network_config, Smithy::Schema::Shapes::ShapeRef.new(shape: RemoteNetworkConfigRequest, location_name: 'remoteNetworkConfig', traits: {"smithy.api#documentation" => "<p>The configuration in the cluster for EKS Hybrid Nodes. You can add, change, or remove this\n            configuration after the cluster is created.</p>"}))
    CreateClusterRequest.add_member(:compute_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ComputeConfigRequest, location_name: 'computeConfig', traits: {"smithy.api#documentation" => "<p>Enable or disable the compute capability of EKS Auto Mode when creating your EKS Auto\n            Mode cluster. If the compute capability is enabled, EKS Auto Mode will create and delete\n            EC2 Managed Instances in your Amazon Web Services account</p>"}))
    CreateClusterRequest.add_member(:storage_config, Smithy::Schema::Shapes::ShapeRef.new(shape: StorageConfigRequest, location_name: 'storageConfig', traits: {"smithy.api#documentation" => "<p>Enable or disable the block storage capability of EKS Auto Mode when creating your EKS\n            Auto Mode cluster. If the block storage capability is enabled, EKS Auto Mode will create\n            and delete EBS volumes in your Amazon Web Services account.</p>"}))
    CreateClusterRequest.add_member(:deletion_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedBoolean, location_name: 'deletionProtection', traits: {"smithy.api#documentation" => "<p>Indicates whether to enable deletion protection for the cluster. When enabled, the cluster \n            cannot be deleted unless deletion protection is first disabled. This helps prevent \n            accidental cluster deletion. Default value is <code>false</code>.</p>"}))
    CreateClusterRequest.type = Types::CreateClusterRequest
    CreateClusterResponse.add_member(:cluster, Smithy::Schema::Shapes::ShapeRef.new(shape: Cluster, location_name: 'cluster', traits: {"smithy.api#documentation" => "<p>The full description of your new cluster.</p>"}))
    CreateClusterResponse.type = Types::CreateClusterResponse
    CreateEksAnywhereSubscriptionRequest.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: EksAnywhereSubscriptionName, location_name: 'name', traits: {"smithy.api#documentation" => "<p>The unique name for your subscription. It must be unique in your Amazon Web Services account in the\n            Amazon Web Services Region you're creating the subscription in. The name can contain only alphanumeric\n            characters (case-sensitive), hyphens, and underscores. It must start with an alphabetic\n            character and can't be longer than 100 characters.</p>", "smithy.api#required" => {}}))
    CreateEksAnywhereSubscriptionRequest.add_member(:term, Smithy::Schema::Shapes::ShapeRef.new(shape: EksAnywhereSubscriptionTerm, location_name: 'term', traits: {"smithy.api#documentation" => "<p>An object representing the term duration and term unit type of your subscription. This\n            determines the term length of your subscription. Valid values are MONTHS for term unit\n            and 12 or 36 for term duration, indicating a 12 month or 36 month subscription. This\n            value cannot be changed after creating the subscription.</p>", "smithy.api#required" => {}}))
    CreateEksAnywhereSubscriptionRequest.add_member(:license_quantity, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'licenseQuantity', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The number of licenses to purchase with the subscription. Valid values are between 1\n            and 100. This value can't be changed after creating the subscription.</p>"}))
    CreateEksAnywhereSubscriptionRequest.add_member(:license_type, Smithy::Schema::Shapes::ShapeRef.new(shape: EksAnywhereSubscriptionLicenseType, location_name: 'licenseType', traits: {"smithy.api#documentation" => "<p>The license type for all licenses in the subscription. Valid value is CLUSTER. With\n            the CLUSTER license type, each license covers support for a single EKS Anywhere\n            cluster.</p>"}))
    CreateEksAnywhereSubscriptionRequest.add_member(:auto_renew, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'autoRenew', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>A boolean indicating whether the subscription auto renews at the end of the\n            term.</p>"}))
    CreateEksAnywhereSubscriptionRequest.add_member(:client_request_token, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'clientRequestToken', traits: {"smithy.api#documentation" => "<p>A unique, case-sensitive identifier that you provide to ensure\nthe idempotency of the request.</p>", "smithy.api#idempotencyToken" => {}}))
    CreateEksAnywhereSubscriptionRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagMap, location_name: 'tags', traits: {"smithy.api#documentation" => "<p>The metadata for a subscription to assist with categorization and organization. Each\n            tag consists of a key and an optional value. Subscription tags don't propagate to any\n            other resources associated with the subscription.</p>"}))
    CreateEksAnywhereSubscriptionRequest.type = Types::CreateEksAnywhereSubscriptionRequest
    CreateEksAnywhereSubscriptionResponse.add_member(:subscription, Smithy::Schema::Shapes::ShapeRef.new(shape: EksAnywhereSubscription, location_name: 'subscription', traits: {"smithy.api#documentation" => "<p>The full description of the subscription.</p>"}))
    CreateEksAnywhereSubscriptionResponse.type = Types::CreateEksAnywhereSubscriptionResponse
    CreateFargateProfileRequest.add_member(:fargate_profile_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'fargateProfileName', traits: {"smithy.api#documentation" => "<p>The name of the Fargate profile.</p>", "smithy.api#required" => {}}))
    CreateFargateProfileRequest.add_member(:cluster_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'clusterName', traits: {"smithy.api#documentation" => "<p>The name of your cluster.</p>", "smithy.api#httpLabel" => {}, "smithy.api#required" => {}}))
    CreateFargateProfileRequest.add_member(:pod_execution_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'podExecutionRoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the <code>Pod</code> execution role to use for a <code>Pod</code>\n            that matches the selectors in the Fargate profile. The <code>Pod</code> execution role\n            allows Fargate infrastructure to register with your cluster as a node, and it provides\n            read access to Amazon ECR image repositories. For more information, see <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/pod-execution-role.html\">\n               <code>Pod</code> execution role</a> in the <i>Amazon EKS User Guide</i>.</p>", "smithy.api#required" => {}}))
    CreateFargateProfileRequest.add_member(:subnets, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'subnets', traits: {"smithy.api#documentation" => "<p>The IDs of subnets to launch a <code>Pod</code> into. A <code>Pod</code> running on\n            Fargate isn't assigned a public IP address, so only private subnets (with no direct\n            route to an Internet Gateway) are accepted for this parameter.</p>"}))
    CreateFargateProfileRequest.add_member(:selectors, Smithy::Schema::Shapes::ShapeRef.new(shape: FargateProfileSelectors, location_name: 'selectors', traits: {"smithy.api#documentation" => "<p>The selectors to match for a <code>Pod</code> to use this Fargate profile. Each\n            selector must have an associated Kubernetes <code>namespace</code>. Optionally, you can also\n            specify <code>labels</code> for a <code>namespace</code>. You may specify up to five\n            selectors in a Fargate profile.</p>"}))
    CreateFargateProfileRequest.add_member(:client_request_token, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'clientRequestToken', traits: {"smithy.api#documentation" => "<p>A unique, case-sensitive identifier that you provide to ensure\nthe idempotency of the request.</p>", "smithy.api#idempotencyToken" => {}}))
    CreateFargateProfileRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagMap, location_name: 'tags', traits: {"smithy.api#documentation" => "<p>Metadata that assists with categorization and organization.\n            Each tag consists of a key and an optional value. You define both. Tags don't\n            propagate to any other cluster or Amazon Web Services resources.</p>"}))
    CreateFargateProfileRequest.type = Types::CreateFargateProfileRequest
    CreateFargateProfileResponse.add_member(:fargate_profile, Smithy::Schema::Shapes::ShapeRef.new(shape: FargateProfile, location_name: 'fargateProfile', traits: {"smithy.api#documentation" => "<p>The full description of your new Fargate profile.</p>"}))
    CreateFargateProfileResponse.type = Types::CreateFargateProfileResponse
    CreateNodegroupRequest.add_member(:cluster_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'clusterName', traits: {"smithy.api#documentation" => "<p>The name of your cluster.</p>", "smithy.api#httpLabel" => {}, "smithy.api#required" => {}}))
    CreateNodegroupRequest.add_member(:nodegroup_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'nodegroupName', traits: {"smithy.api#documentation" => "<p>The unique name to give your node group.</p>", "smithy.api#required" => {}}))
    CreateNodegroupRequest.add_member(:scaling_config, Smithy::Schema::Shapes::ShapeRef.new(shape: NodegroupScalingConfig, location_name: 'scalingConfig', traits: {"smithy.api#documentation" => "<p>The scaling configuration details for the Auto Scaling group that is created for your\n            node group.</p>"}))
    CreateNodegroupRequest.add_member(:disk_size, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedInteger, location_name: 'diskSize', traits: {"smithy.api#documentation" => "<p>The root device disk size (in GiB) for your node group instances. The default disk\n            size is 20 GiB for Linux and Bottlerocket. The default disk size is 50 GiB for Windows.\n            If you specify <code>launchTemplate</code>, then don't specify  <code>diskSize</code>, or the node group \n            deployment will fail. For more information about using launch templates with Amazon EKS, see <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/launch-templates.html\">Customizing managed nodes with launch templates</a> in the <i>Amazon EKS User Guide</i>.</p>"}))
    CreateNodegroupRequest.add_member(:subnets, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'subnets', traits: {"smithy.api#documentation" => "<p>The subnets to use for the Auto Scaling group that is created for your node group.\n            If you specify <code>launchTemplate</code>, then don't specify  <code>\n               <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_CreateNetworkInterface.html\">SubnetId</a>\n            </code> in your launch template, or the node group  deployment\n            will fail. For more information about using launch templates with Amazon EKS, see <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/launch-templates.html\">Customizing managed nodes with launch templates</a> in the <i>Amazon EKS User Guide</i>.</p>", "smithy.api#required" => {}}))
    CreateNodegroupRequest.add_member(:instance_types, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'instanceTypes', traits: {"smithy.api#documentation" => "<p>Specify the instance types for a node group. If you specify a GPU instance type, make\n            sure to also specify an applicable GPU AMI type with the <code>amiType</code> parameter.\n            If you specify <code>launchTemplate</code>, then you can specify zero or one instance\n            type in your launch template <i>or</i> you can specify 0-20 instance types\n            for <code>instanceTypes</code>. If however, you specify an instance type in your launch\n            template <i>and</i> specify any <code>instanceTypes</code>, the node group\n            deployment will fail. If you don't specify an instance type in a launch template or for\n                <code>instanceTypes</code>, then <code>t3.medium</code> is used, by default. If you\n            specify <code>Spot</code> for <code>capacityType</code>, then we recommend specifying\n            multiple values for <code>instanceTypes</code>. For more information, see <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/managed-node-groups.html#managed-node-group-capacity-types\">Managed node group capacity types</a> and <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/launch-templates.html\">Customizing managed nodes with\n                launch templates</a> in the <i>Amazon EKS User Guide</i>.</p>"}))
    CreateNodegroupRequest.add_member(:ami_type, Smithy::Schema::Shapes::ShapeRef.new(shape: AMITypes, location_name: 'amiType', traits: {"smithy.api#documentation" => "<p>The AMI type for your node group. If you specify <code>launchTemplate</code>, and your launch template uses a custom AMI,\n                then don't specify <code>amiType</code>, or the node group  deployment\n            will fail. If your launch template uses a Windows custom AMI, then add\n                <code>eks:kube-proxy-windows</code> to your Windows nodes <code>rolearn</code> in\n            the <code>aws-auth</code>\n            <code>ConfigMap</code>. For more information about using launch templates with Amazon EKS, see <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/launch-templates.html\">Customizing managed nodes with launch templates</a> in the <i>Amazon EKS User Guide</i>.</p>"}))
    CreateNodegroupRequest.add_member(:remote_access, Smithy::Schema::Shapes::ShapeRef.new(shape: RemoteAccessConfig, location_name: 'remoteAccess', traits: {"smithy.api#documentation" => "<p>The remote access configuration to use with your node group. For Linux, the protocol\n            is SSH. For Windows, the protocol is RDP. If you specify <code>launchTemplate</code>, then don't specify \n                <code>remoteAccess</code>, or the node group  deployment will fail.\n            For more information about using launch templates with Amazon EKS, see <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/launch-templates.html\">Customizing managed nodes with launch templates</a> in the <i>Amazon EKS User Guide</i>.</p>"}))
    CreateNodegroupRequest.add_member(:node_role, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'nodeRole', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the IAM role to associate with your node group. The Amazon EKS worker\n            node <code>kubelet</code> daemon makes calls to Amazon Web Services APIs on your behalf. Nodes receive\n            permissions for these API calls through an IAM instance profile and associated\n            policies. Before you can launch nodes and register them into a cluster, you must create\n            an IAM role for those nodes to use when they are launched. For more information, see\n                <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/create-node-role.html\">Amazon EKS\n                node IAM role</a> in the <i>\n               <i>Amazon EKS User Guide</i>\n            </i>.\n            If you specify <code>launchTemplate</code>, then don't specify  <code>\n               <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_IamInstanceProfile.html\">IamInstanceProfile</a>\n            </code> in your launch template, or the node group \n            deployment will fail. For more information about using launch templates with Amazon EKS, see <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/launch-templates.html\">Customizing managed nodes with launch templates</a> in the <i>Amazon EKS User Guide</i>.</p>", "smithy.api#required" => {}}))
    CreateNodegroupRequest.add_member(:labels, Smithy::Schema::Shapes::ShapeRef.new(shape: LabelsMap, location_name: 'labels', traits: {"smithy.api#documentation" => "<p>The Kubernetes <code>labels</code> to apply to the nodes in the node group when they are\n            created.</p>"}))
    CreateNodegroupRequest.add_member(:taints, Smithy::Schema::Shapes::ShapeRef.new(shape: TaintsList, location_name: 'taints', traits: {"smithy.api#documentation" => "<p>The Kubernetes taints to be applied to the nodes in the node group. For more information,\n            see <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/node-taints-managed-node-groups.html\">Node taints on\n                managed node groups</a>.</p>"}))
    CreateNodegroupRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagMap, location_name: 'tags', traits: {"smithy.api#documentation" => "<p>Metadata that assists with categorization and organization.\n            Each tag consists of a key and an optional value. You define both. Tags don't\n            propagate to any other cluster or Amazon Web Services resources.</p>"}))
    CreateNodegroupRequest.add_member(:client_request_token, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'clientRequestToken', traits: {"smithy.api#documentation" => "<p>A unique, case-sensitive identifier that you provide to ensure\nthe idempotency of the request.</p>", "smithy.api#idempotencyToken" => {}}))
    CreateNodegroupRequest.add_member(:launch_template, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateSpecification, location_name: 'launchTemplate', traits: {"smithy.api#documentation" => "<p>An object representing a node group's launch template specification. When using this\n            object, don't directly specify <code>instanceTypes</code>, <code>diskSize</code>, or\n                <code>remoteAccess</code>. You cannot later specify a different launch template ID\n            or name than what was used to create the node group.</p>\n         <p>Make sure that the launch template meets the requirements in\n                <code>launchTemplateSpecification</code>. Also refer to <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/launch-templates.html\">Customizing managed nodes with\n                launch templates</a> in the <i>Amazon EKS User Guide</i>.</p>"}))
    CreateNodegroupRequest.add_member(:update_config, Smithy::Schema::Shapes::ShapeRef.new(shape: NodegroupUpdateConfig, location_name: 'updateConfig', traits: {"smithy.api#documentation" => "<p>The node group update configuration.</p>"}))
    CreateNodegroupRequest.add_member(:node_repair_config, Smithy::Schema::Shapes::ShapeRef.new(shape: NodeRepairConfig, location_name: 'nodeRepairConfig', traits: {"smithy.api#documentation" => "<p>The node auto repair configuration for the node group.</p>"}))
    CreateNodegroupRequest.add_member(:capacity_type, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityTypes, location_name: 'capacityType', traits: {"smithy.api#documentation" => "<p>The capacity type for your node group.</p>"}))
    CreateNodegroupRequest.add_member(:version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'version', traits: {"smithy.api#documentation" => "<p>The Kubernetes version to use for your managed nodes. By default, the Kubernetes version of the\n            cluster is used, and this is the only accepted specified value. If you specify <code>launchTemplate</code>,\n            and your launch template uses a custom AMI, then don't specify  <code>version</code>, or the node group \n            deployment will fail. For more information about using launch templates with Amazon EKS, see <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/launch-templates.html\">Customizing managed nodes with launch templates</a> in the <i>Amazon EKS User Guide</i>.</p>"}))
    CreateNodegroupRequest.add_member(:release_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'releaseVersion', traits: {"smithy.api#documentation" => "<p>The AMI version of the Amazon EKS optimized AMI to use with your node group. By default,\n            the latest available AMI version for the node group's current Kubernetes version is used. For\n            information about Linux versions, see <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/eks-linux-ami-versions.html\">Amazon EKS\n                optimized Amazon Linux AMI versions</a> in the <i>Amazon EKS User Guide</i>. Amazon EKS managed node\n            groups support the November 2022 and later releases of the Windows AMIs. For information\n            about Windows versions, see <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/eks-ami-versions-windows.html\">Amazon EKS\n                optimized Windows AMI versions</a> in the <i>Amazon EKS User Guide</i>.</p>\n         <p>If you specify <code>launchTemplate</code>, and your launch template uses a custom AMI, then don't specify \n                <code>releaseVersion</code>, or the node group  deployment will fail.\n            For more information about using launch templates with Amazon EKS, see <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/launch-templates.html\">Customizing managed nodes with launch templates</a> in the <i>Amazon EKS User Guide</i>.</p>"}))
    CreateNodegroupRequest.type = Types::CreateNodegroupRequest
    CreateNodegroupResponse.add_member(:nodegroup, Smithy::Schema::Shapes::ShapeRef.new(shape: Nodegroup, location_name: 'nodegroup', traits: {"smithy.api#documentation" => "<p>The full description of your new node group.</p>"}))
