    OidcIdentityProviderConfigRequest.add_member(:identity_provider_config_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'identityProviderConfigName', traits: {"smithy.api#documentation" => "<p>The name of the OIDC provider configuration.</p>", "smithy.api#required" => {}}))
    OidcIdentityProviderConfigRequest.add_member(:issuer_url, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'issuerUrl', traits: {"smithy.api#documentation" => "<p>The URL of the OIDC identity provider that allows the API server to discover public\n            signing keys for verifying tokens. The URL must begin with <code>https://</code> and\n            should correspond to the <code>iss</code> claim in the provider's OIDC ID tokens.\n            Based on the OIDC standard, path components are allowed but query parameters are not.\n            Typically the URL consists of only a hostname, like\n                <code>https://server.example.org</code> or <code>https://example.com</code>. This\n            URL should point to the level below <code>.well-known/openid-configuration</code> and\n            must be publicly accessible over the internet.</p>", "smithy.api#required" => {}}))
    OidcIdentityProviderConfigRequest.add_member(:client_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'clientId', traits: {"smithy.api#documentation" => "<p>This is also known as <i>audience</i>. The ID for the client application\n            that makes authentication requests to the OIDC identity provider.</p>", "smithy.api#required" => {}}))
    OidcIdentityProviderConfigRequest.add_member(:username_claim, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'usernameClaim', traits: {"smithy.api#documentation" => "<p>The JSON Web Token (JWT) claim to use as the username. The default is\n            <code>sub</code>, which is expected to be a unique identifier of the end user. You can\n            choose other claims, such as <code>email</code> or <code>name</code>, depending on the\n            OIDC identity provider. Claims other than <code>email</code> are prefixed with the\n            issuer URL to prevent naming clashes with other plug-ins.</p>"}))
    OidcIdentityProviderConfigRequest.add_member(:username_prefix, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'usernamePrefix', traits: {"smithy.api#documentation" => "<p>The prefix that is prepended to username claims to prevent clashes with existing\n            names. If you do not provide this field, and <code>username</code> is a value other than\n                <code>email</code>, the prefix defaults to <code>issuerurl#</code>. You can use the\n            value <code>-</code> to disable all prefixing.</p>"}))
    OidcIdentityProviderConfigRequest.add_member(:groups_claim, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'groupsClaim', traits: {"smithy.api#documentation" => "<p>The JWT claim that the provider uses to return your groups.</p>"}))
    OidcIdentityProviderConfigRequest.add_member(:groups_prefix, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'groupsPrefix', traits: {"smithy.api#documentation" => "<p>The prefix that is prepended to group claims to prevent clashes with existing names\n            (such as <code>system:</code> groups). For example, the value<code> oidc:</code> will\n            create group names like <code>oidc:engineering</code> and\n            <code>oidc:infra</code>.</p>"}))
    OidcIdentityProviderConfigRequest.add_member(:required_claims, Smithy::Schema::Shapes::ShapeRef.new(shape: RequiredClaimsMap, location_name: 'requiredClaims', traits: {"smithy.api#documentation" => "<p>The key value pairs that describe required claims in the identity token. If set, each\n            claim is verified to be present in the token with a matching value. For the maximum\n            number of claims that you can require, see <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/service-quotas.html\">Amazon EKS service quotas</a> in the\n            <i>Amazon EKS User Guide</i>.</p>"}))
