    VpcConfigRequest.add_member(:subnet_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'subnetIds', traits: {"smithy.api#documentation" => "<p>Specify subnets for your Amazon EKS nodes. Amazon EKS creates cross-account elastic network\n            interfaces in these subnets to allow communication between your nodes and the Kubernetes\n            control plane.</p>"}))
    VpcConfigRequest.add_member(:security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'securityGroupIds', traits: {"smithy.api#documentation" => "<p>Specify one or more security groups for the cross-account elastic network interfaces\n            that Amazon EKS creates to use that allow communication between your nodes and the Kubernetes\n            control plane. If you don't specify any security groups, then familiarize yourself with\n            the difference between Amazon EKS defaults for clusters deployed with Kubernetes. For more\n            information, see <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/sec-group-reqs.html\">Amazon EKS security group\n                considerations</a> in the <i>\n               <i>Amazon EKS User Guide</i>\n            </i>.</p>"}))
    VpcConfigRequest.add_member(:endpoint_public_access, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedBoolean, location_name: 'endpointPublicAccess', traits: {"smithy.api#documentation" => "<p>Set this value to <code>false</code> to disable public access to your cluster's Kubernetes\n            API server endpoint. If you disable public access, your cluster's Kubernetes API server can\n            only receive requests from within the cluster VPC. The default value for this parameter\n            is <code>true</code>, which enables public access for your Kubernetes API server. The\n            endpoint domain name and IP address family depends on the value of the\n                <code>ipFamily</code> for the cluster. For more information, see <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/cluster-endpoint.html\">Cluster API\n                server endpoint</a> in the <i>\n               <i>Amazon EKS User Guide</i>\n            </i>.</p>"}))
    VpcConfigRequest.add_member(:endpoint_private_access, Smithy::Schema::Shapes::ShapeRef.new(shape: BoxedBoolean, location_name: 'endpointPrivateAccess', traits: {"smithy.api#documentation" => "<p>Set this value to <code>true</code> to enable private access for your cluster's Kubernetes\n            API server endpoint. If you enable private access, Kubernetes API requests from within your\n            cluster's VPC use the private VPC endpoint. The default value for this parameter is\n                <code>false</code>, which disables private access for your Kubernetes API server. If you\n            disable private access and you have nodes or Fargate pods in the cluster, then\n            ensure that <code>publicAccessCidrs</code> includes the necessary CIDR blocks for\n            communication with the nodes or Fargate pods. For more information, see <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/cluster-endpoint.html\">Cluster\n                API server endpoint</a> in the <i>\n               <i>Amazon EKS User Guide</i>\n            </i>.</p>"}))
    VpcConfigRequest.add_member(:public_access_cidrs, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'publicAccessCidrs', traits: {"smithy.api#documentation" => "<p>The CIDR blocks that are allowed access to your cluster's public Kubernetes API server\n            endpoint. Communication to the endpoint from addresses outside of the CIDR blocks that\n            you specify is denied. The default value is <code>0.0.0.0/0</code> and additionally\n                <code>::/0</code> for dual-stack `IPv6` clusters. If you've disabled private\n            endpoint access, make sure that you specify the necessary CIDR blocks for every node and\n            Fargate <code>Pod</code> in the cluster. For more information, see <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/cluster-endpoint.html\">Cluster\n                API server endpoint</a> in the <i>\n               <i>Amazon EKS User Guide</i>\n            </i>.</p>\n         <p>Note that the public endpoints are dual-stack for only <code>IPv6</code> clusters that\n            are made after October 2024. You can't add <code>IPv6</code> CIDR blocks to\n                <code>IPv4</code> clusters or <code>IPv6</code> clusters that were made before\n            October 2024.</p>"}))
    VpcConfigRequest.type = Types::VpcConfigRequest
    VpcConfigResponse.add_member(:subnet_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'subnetIds', traits: {"smithy.api#documentation" => "<p>The subnets associated with your cluster.</p>"}))
    VpcConfigResponse.add_member(:security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'securityGroupIds', traits: {"smithy.api#documentation" => "<p>The security groups associated with the cross-account elastic network interfaces that\n            are used to allow communication between your nodes and the Kubernetes control plane.</p>"}))
    VpcConfigResponse.add_member(:cluster_security_group_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'clusterSecurityGroupId', traits: {"smithy.api#documentation" => "<p>The cluster security group that was created by Amazon EKS for the cluster. Managed node\n            groups use this security group for control-plane-to-data-plane communication.</p>"}))
    VpcConfigResponse.add_member(:vpc_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'vpcId', traits: {"smithy.api#documentation" => "<p>The VPC associated with your cluster.</p>"}))
    VpcConfigResponse.add_member(:endpoint_public_access, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'endpointPublicAccess', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Whether the public API server endpoint is enabled.</p>"}))
    VpcConfigResponse.add_member(:endpoint_private_access, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'endpointPrivateAccess', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>This parameter indicates whether the Amazon EKS private API server endpoint is enabled. If\n            the Amazon EKS private API server endpoint is enabled, Kubernetes API requests that originate from\n            within your cluster's VPC use the private VPC endpoint instead of traversing the\n            internet. If this value is disabled and you have nodes or Fargate pods in the\n            cluster, then ensure that <code>publicAccessCidrs</code> includes the necessary CIDR\n            blocks for communication with the nodes or Fargate pods. For more information, see\n                <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/cluster-endpoint.html\">Cluster\n                API server endpoint</a> in the <i>\n               <i>Amazon EKS User Guide</i>\n            </i>.</p>"}))
    VpcConfigResponse.add_member(:public_access_cidrs, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'publicAccessCidrs', traits: {"smithy.api#documentation" => "<p>The CIDR blocks that are allowed access to your cluster's public Kubernetes API server\n            endpoint. Communication to the endpoint from addresses outside of the CIDR blocks that\n            you specify is denied. The default value is <code>0.0.0.0/0</code> and additionally\n            <code>::/0</code> for dual-stack `IPv6` clusters. If you've disabled private\n            endpoint access, make sure that you specify the necessary CIDR blocks for every node and\n            Fargate <code>Pod</code> in the cluster. For more information, see <a href=\"https://docs.aws.amazon.com/eks/latest/userguide/cluster-endpoint.html\">Cluster\n                API server endpoint</a> in the <i>\n               <i>Amazon EKS User Guide</i>\n            </i>.</p>\n         <p>Note that the public endpoints are dual-stack for only <code>IPv6</code> clusters that\n            are made after October 2024. You can't add <code>IPv6</code> CIDR blocks to\n            <code>IPv4</code> clusters or <code>IPv6</code> clusters that were made before\n            October 2024.</p>"}))
